<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'add';if($action==='add'){$name=trim($_POST['customer_name']??'');$phone=trim($_POST['phone']??'');$date=$_POST['booking_date']??'';$time=$_POST['booking_time']??'';$people=max(1,min(200,(int)($_POST['people']??1)));$type=$_POST['booking_type']??'General swim';$notes=trim($_POST['notes']??'');if($name&&$date&&$time){$st=$pdo->prepare("INSERT INTO bookings(customer_name,phone,booking_date,booking_time,people,booking_type,notes,status,created_by) VALUES(?,?,?,?,?,?,?,'booked',?)");$st->execute([$name,$phone,$date,$time,$people,$type,$notes,current_user()['id']]);flash('Booking created.');}}elseif($action==='status'){$id=(int)$_POST['id'];$status=$_POST['status']??'booked';if(in_array($status,['booked','arrived','cancelled'],true))$pdo->prepare("UPDATE bookings SET status=? WHERE id=?")->execute([$status,$id]);flash('Booking updated.');}redirect('bookings.php');}
$rows=$pdo->query("SELECT * FROM bookings ORDER BY booking_date DESC,booking_time DESC LIMIT 200")->fetchAll();layout_start('Bookings','bookings');?>
<div class="page-actions"><div><p class="muted">Plan swim visits, groups, lessons, and pool reservations.</p></div><button class="btn primary" onclick="document.getElementById('bookingForm').classList.toggle('hidden')">＋ New booking</button></div><section class="panel form-panel hidden" id="bookingForm"><h3>Create booking</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Customer / group name *<input name="customer_name" required></label><label>Phone<input name="phone"></label><label>Date *<input type="date" name="booking_date" min="<?=date('Y-m-d')?>" value="<?=date('Y-m-d')?>" required></label><label>Time *<input type="time" name="booking_time" value="10:00" required></label><label>People<input type="number" name="people" min="1" max="200" value="1"></label><label>Booking type<select name="booking_type"><option>General swim</option><option>Swimming lessons</option><option>Group booking</option><option>Birthday / event</option></select></label><label class="span-2">Notes<input name="notes" placeholder="Optional notes"></label><div class="form-actions"><button class="btn primary">Save booking</button></div></form></section><section class="panel table-panel"><div class="panel-head"><div><h3>Booking schedule</h3><p class="muted"><?=count($rows)?> recent bookings</p></div></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Date & time</th><th>People</th><th>Type</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=h($r['customer_name'])?></b><small class="table-sub"><?=h($r['phone']?:'')?></small></td><td><?=date('d M Y',strtotime($r['booking_date']))?><small class="table-sub"><?=date('h:i A',strtotime($r['booking_time']))?></small></td><td><?=$r['people']?></td><td><?=h($r['booking_type'])?></td><td><span class="badge <?= $r['status']==='arrived'?'success':($r['status']==='cancelled'?'danger':'soft')?>"><?=h($r['status'])?></span></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" aria-label="Booking status"><option value="booked" <?=$r['status']==='booked'?'selected':''?>>Booked</option><option value="arrived" <?=$r['status']==='arrived'?'selected':''?>>Arrived</option><option value="cancelled" <?=$r['status']==='cancelled'?'selected':''?>>Cancelled</option></select><button class="btn small secondary">Save</button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="empty">No bookings yet.</td></tr><?php endif;?></tbody></table></div></section><?php layout_end();?>
